mapper.select:
SELECT ar.id, ar.rule_code AS ruleCode, ar.rule_name AS ruleName, ar.rule_type AS ruleType, CASE ar.rule_type WHEN 'threshold' THEN '阈值' WHEN 'compare' THEN '比较' WHEN 'trend' THEN '趋势' ELSE '其他' END AS ruleTypeText, ar.device_type_id AS deviceTypeId, dt.type_name AS deviceTypeName, ar.property_code AS propertyCode, ar.property_name AS propertyName, ar.operator, ar.threshold_value AS thresholdValue, ar.duration_seconds AS durationSeconds, ar.alert_level AS alertLevel, CASE ar.alert_level WHEN 1 THEN '紧急' WHEN 2 THEN '重要' WHEN 3 THEN '一般' WHEN 4 THEN '提醒' ELSE '未知' END AS alertLevelText, ar.alert_channel AS alertChannel, ar.alert_template AS alertTemplate, ar.enable_status AS enableStatus, CASE ar.enable_status WHEN 1 THEN '启用' ELSE '禁用' END AS enableStatusText, ar.create_by AS createBy, ar.create_time AS createTime FROM agri_iot_alert_rule ar LEFT JOIN agri_iot_device_type dt ON ar.device_type_id = dt.id WHERE ar.del_flag = 0
AND ar.rule_code LIKE CONCAT('%', #{dto.ruleCode}, '%')
AND ar.rule_name LIKE CONCAT('%', #{dto.ruleName}, '%')
AND ar.rule_type = #{dto.ruleType}
AND ar.device_type_id = #{dto.deviceTypeId}
AND ar.enable_status = #{dto.enableStatus}
ORDER BY ar.create_time DESC LIMIT #{dto.pageNum}, #{dto.pageSize}

SELECT COUNT(*)
FROM agri_iot_alert_rule ar
WHERE ar.del_flag = 0

    AND ar.rule_code LIKE CONCAT('%', #{dto.ruleCode}, '%')


    AND ar.rule_name LIKE CONCAT('%', #{dto.ruleName}, '%')


    AND ar.rule_type = #{dto.ruleType}


    AND ar.device_type_id = #{dto.deviceTypeId}


    AND ar.enable_status = #{dto.enableStatus}
